// CoHostJoinScreen.swift
// BidCast
//
// Basecamp #9934001770 (2026-05-29): co-host SECOND DEVICE join flow.
// The seller on the second device enters the 6-character pairing code
// generated by the host on the primary device.  On success the backend
// marks the pairing row as "active" and the primary device's polling loop
// (in CoHostPairingSheet) detects the join and dismisses automatically.
//
// Entry point: ShowsScreen → "Join as Co-Host" button (bottom of the shows
// list) for sellers, or via SellerHub menu.
//
// Agora multi-publisher (2026-05-29):
// After the control-pairing claim succeeds we compute the channel name
//   "live_room_\(show.user_id)_\(show.id)"
// (identical format to RehearsalScreen.fetchAgoraToken), fetch an Agora
// broadcaster token via the existing /api/agora-token endpoint with uid
// omitted so Agora auto-assigns a distinct UID, then join the channel with
// clientRoleType = .broadcaster so both camera feeds publish simultaneously.
// The local camera feed is shown full-screen; the host's remote feed appears
// as a compact PiP overlay once didJoinedOfUid fires.

import SwiftUI
import AlertToast
import AVFoundation

struct CoHostJoinScreen: View {

    @Environment(\.presentationMode) var presentationMode
    let inviteId: Int?

    init(inviteId: Int? = nil) {
        self.inviteId = inviteId
    }

    // MARK: - Agora objects (reuse existing manager + view-model)
    @StateObject private var agoraViewModel = AgoraViewModel()
    @StateObject private var agoraManager   = AgoraManager(asHost: true)
    @StateObject private var socketManager  = SocketManagerService.shared

    // MARK: - Pairing State
    @State private var pairingCode: String = ""
    @State private var isJoining: Bool = false
    @State private var joinedShowTitle: String? = nil
    @State private var joinError: String? = nil
    @FocusState private var codeFocused: Bool

    @State private var showhud = false
    @State private var hudMsg  = ""

    // MARK: - Invite State
    @State private var inviteLoaded = false
    @State private var isLoadingInvite = false
    @State private var isRespondingToInvite = false
    @State private var inviteStatus: String = ""
    @State private var inviteHostName: String = ""
    @State private var inviteShowTitle: String = ""
    @State private var inviteScheduleShowId: Int = 0
    @State private var inviteHostUserId: Int = 0
    @State private var showInviteProductSelection = false
    @State private var eligibleInviteProducts: [ProductDataModel1] = []
    @State private var selectedInviteProductIds: Set<Int> = []
    @State private var activeCoHostId: Int?
    @State private var activeRoomId: String = ""
    @State private var activeShowId: Int = 0
    @State private var coHostCommentText: String = ""
    @State private var showCoHostProducts = false
    @State private var coHostShowProducts: [ProductDataModel1] = []

    // MARK: - Co-host Live State
    @State private var isLive: Bool        = false
    @State private var isJoiningAgora: Bool = false
    @State private var agoraError: String? = nil
    @State private var permissionDenied: Bool = false

    // MARK: - Body
    var body: some View {
        if isLive {
            coHostLiveView
        } else if inviteId != nil {
            inviteView
        } else {
            pairingView
        }
    }

    @ViewBuilder
    private var inviteView: some View {
        VStack(spacing: 0) {
            PrimaryHeader(
                title: "Co-Host Invite",
                isForLogo: false,
                leadingImgArr: ["chevron.left"],
                trailingImgArr: [],
                onClickLeading: { _ in presentationMode.wrappedValue.dismiss() },
                count: .constant(0)
            )

            ScrollView(showsIndicators: false) {
                VStack(spacing: 22) {
                    if isLoadingInvite {
                        ProgressView()
                            .padding(.top, 80)
                    } else if !inviteLoaded {
                        Text(joinError ?? "Could not load invite.")
                            .font(.custom(poppinsRegular, size: 14))
                            .foregroundColor(.red)
                            .multilineTextAlignment(.center)
                            .padding(.top, 80)
                            .padding(.horizontal, 24)
                    } else if showInviteProductSelection {
                        inviteProductSelectionView
                    } else {
                        inviteDecisionView
                    }
                }
                .padding(.bottom, 40)
            }
        }
        .background(Color.backGround)
        .navigationBarHidden(true)
        .toast(isPresenting: $showhud) {
            AlertToast(displayMode: .hud, type: .regular, title: hudMsg)
        }
        .onAppear {
            guard !inviteLoaded, !isLoadingInvite else { return }
            Task { await loadInviteDetail() }
        }
        .onDisappear {
            if !isLive && agoraManager.isJoined {
                agoraManager.leaveChannel()
            }
        }
    }

    private var inviteDecisionView: some View {
        VStack(spacing: 22) {
            Image(systemName: "person.2.fill")
                .font(.system(size: 54, weight: .semibold))
                .foregroundColor(.defaultTheme)
                .padding(.top, 32)

            VStack(spacing: 10) {
                Text("\(inviteHostName.isEmpty ? "A seller" : inviteHostName) has invited you to be a cohost for their Live: \(inviteShowTitle.isEmpty ? "Live show" : inviteShowTitle). Would you like to accept?")
                    .font(.custom(poppinsSemiBold, size: 17))
                    .foregroundColor(.primary)
                    .multilineTextAlignment(.center)
                    .padding(.horizontal, 24)

                if !inviteStatus.isEmpty && inviteStatus != "pending" {
                    Text("Invite is \(inviteStatus).")
                        .font(.custom(poppinsRegular, size: 13))
                        .foregroundColor(.gray)
                }
            }

            HStack(spacing: 12) {
                Button {
                    Task { await respondToInvite(accept: false, productIds: []) }
                } label: {
                    Text("No")
                        .font(.custom(poppinsBold, size: 16))
                        .foregroundColor(.defaultTheme)
                        .frame(maxWidth: .infinity)
                        .frame(height: 52)
                        .background(Color.defaultTheme.opacity(0.08))
                        .cornerRadius(26)
                }
                .disabled(isRespondingToInvite || inviteStatus != "pending")

                Button {
                    Task { await loadEligibleProductsForInvite() }
                } label: {
                    ZStack {
                        if isRespondingToInvite {
                            ProgressView().tint(.white)
                        } else {
                            Text("Yes")
                                .font(.custom(poppinsBold, size: 16))
                        }
                    }
                    .foregroundColor(.white)
                    .frame(maxWidth: .infinity)
                    .frame(height: 52)
                    .background(Color.defaultTheme)
                    .cornerRadius(26)
                }
                .disabled(isRespondingToInvite || inviteStatus != "pending")
            }
            .padding(.horizontal, 24)
        }
    }

    private var inviteProductSelectionView: some View {
        VStack(alignment: .leading, spacing: 18) {
            VStack(alignment: .leading, spacing: 8) {
                Text("Would you like to add products to the show?")
                    .font(.custom(poppinsBold, size: 21))
                    .foregroundColor(.primary)

                Text("You can join without selecting products.")
                    .font(.custom(poppinsRegular, size: 13))
                    .foregroundColor(.gray)
            }
            .padding(.horizontal, 20)
            .padding(.top, 24)

            if eligibleInviteProducts.isEmpty {
                Text("No eligible products found.")
                    .font(.custom(poppinsRegular, size: 14))
                    .foregroundColor(.gray)
                    .frame(maxWidth: .infinity, alignment: .center)
                    .padding(.vertical, 36)
            } else {
                VStack(spacing: 10) {
                    ForEach(eligibleInviteProducts, id: \.id) { product in
                        inviteProductRow(product)
                    }
                }
                .padding(.horizontal, 16)
            }

            Button {
                Task {
                    await respondToInvite(
                        accept: true,
                        productIds: Array(selectedInviteProductIds)
                    )
                }
            } label: {
                ZStack {
                    if isRespondingToInvite {
                        ProgressView().tint(.white)
                    } else {
                        Text("Join as cohost")
                            .font(.custom(poppinsBold, size: 16))
                    }
                }
                .foregroundColor(.white)
                .frame(maxWidth: .infinity)
                .frame(height: 56)
                .background(Color.defaultTheme)
                .cornerRadius(28)
            }
            .disabled(isRespondingToInvite)
            .padding(.horizontal, 20)
            .padding(.top, 10)
        }
    }

    private func inviteProductRow(_ product: ProductDataModel1) -> some View {
        let productId = product.id ?? 0
        let isSelected = selectedInviteProductIds.contains(productId)
        return Button {
            if isSelected {
                selectedInviteProductIds.remove(productId)
            } else {
                selectedInviteProductIds.insert(productId)
            }
        } label: {
            HStack(spacing: 12) {
                Image(systemName: isSelected ? "checkmark.circle.fill" : "circle")
                    .font(.system(size: 22, weight: .semibold))
                    .foregroundColor(isSelected ? .defaultTheme : .gray.opacity(0.7))

                VStack(alignment: .leading, spacing: 4) {
                    Text(product.title ?? "Untitled product")
                        .font(.custom(poppinsSemiBold, size: 15))
                        .foregroundColor(.primary)
                        .lineLimit(2)
                    Text("$\(product.pricing ?? "0.00")")
                        .font(.custom(poppinsRegular, size: 13))
                        .foregroundColor(.gray)
                }

                Spacer()
            }
            .padding(14)
            .background(Color(.systemBackground))
            .cornerRadius(12)
            .overlay(
                RoundedRectangle(cornerRadius: 12)
                    .stroke(isSelected ? Color.defaultTheme.opacity(0.6) : Color.gray.opacity(0.12), lineWidth: 1)
            )
        }
        .buttonStyle(.plain)
    }

    // MARK: - Pairing / Code Entry View
    @ViewBuilder
    private var pairingView: some View {
        VStack(spacing: 0) {
            PrimaryHeader(
                title: "Join as Co-Host",
                isForLogo: false,
                leadingImgArr: ["chevron.left"],
                trailingImgArr: [],
                onClickLeading: { _ in presentationMode.wrappedValue.dismiss() },
                count: .constant(0)
            )

            ScrollView(showsIndicators: false) {
                VStack(spacing: 28) {

                    // Icon
                    Image(systemName: "iphone.and.arrow.forward")
                        .font(.system(size: 64, weight: .light))
                        .foregroundColor(.defaultTheme)
                        .padding(.top, 32)

                    VStack(spacing: 8) {
                        Text("Enter Pairing Code")
                            .font(.custom(poppinsBold, size: 22))
                            .foregroundColor(.primary)

                        Text("Have the primary device generate a co-host code, then enter it below.")
                            .font(.custom(poppinsRegular, size: 13))
                            .foregroundColor(.gray)
                            .multilineTextAlignment(.center)
                            .padding(.horizontal, 32)
                    }

                    // Code input
                    VStack(spacing: 8) {
                        TextField("e.g. AB12C3", text: $pairingCode)
                            .focused($codeFocused)
                            .font(.system(size: 28, weight: .heavy, design: .monospaced))
                            .multilineTextAlignment(.center)
                            .textInputAutocapitalization(.characters)
                            .autocorrectionDisabled(true)
                            .onChange(of: pairingCode) { _, v in
                                // Uppercase + limit to 6 alphanumeric chars
                                let cleaned = String(v.uppercased()
                                    .filter { $0.isLetter || $0.isNumber }
                                    .prefix(6))
                                if pairingCode != cleaned { pairingCode = cleaned }
                            }
                            .padding(.vertical, 16)
                            .background(
                                RoundedRectangle(cornerRadius: 16)
                                    .fill(Color(.systemGray6))
                            )
                            .overlay(
                                RoundedRectangle(cornerRadius: 16)
                                    .stroke(
                                        codeFocused ? Color.defaultTheme.opacity(0.6) : Color.gray.opacity(0.2),
                                        lineWidth: codeFocused ? 1.5 : 1
                                    )
                            )
                            .padding(.horizontal, 48)

                        if let err = joinError {
                            Text(err)
                                .font(.custom(poppinsRegular, size: 12))
                                .foregroundColor(.red)
                                .multilineTextAlignment(.center)
                        }
                    }

                    // Agora connecting indicator
                    if isJoiningAgora {
                        VStack(spacing: 8) {
                            ProgressView()
                            Text("Connecting to live stream…")
                                .font(.custom(poppinsRegular, size: 13))
                                .foregroundColor(.gray)
                        }
                    }

                    // Agora error
                    if let agoraErr = agoraError {
                        Text(agoraErr)
                            .font(.custom(poppinsRegular, size: 12))
                            .foregroundColor(.red)
                            .multilineTextAlignment(.center)
                            .padding(.horizontal, 24)
                    }

                    // Permission denied warning
                    if permissionDenied {
                        Text("Camera and/or microphone access was denied. Please allow access in Settings to use co-host video.")
                            .font(.custom(poppinsRegular, size: 12))
                            .foregroundColor(.orange)
                            .multilineTextAlignment(.center)
                            .padding(.horizontal, 24)
                    }

                    // Pairing success confirmation (shown briefly while Agora connects)
                    if let showTitle = joinedShowTitle, !isLive {
                        VStack(spacing: 12) {
                            Image(systemName: "checkmark.circle.fill")
                                .font(.system(size: 48))
                                .foregroundColor(.green)
                            Text("Paired successfully")
                                .font(.custom(poppinsBold, size: 18))
                                .foregroundColor(.green)
                            Text(showTitle)
                                .font(.custom(poppinsRegular, size: 13))
                                .foregroundColor(.gray)
                                .multilineTextAlignment(.center)
                            if !isJoiningAgora {
                                Text("Joining live channel as broadcaster…")
                                    .font(.custom(poppinsRegular, size: 12))
                                    .foregroundColor(.secondary)
                                    .multilineTextAlignment(.center)
                                    .padding(.horizontal, 24)
                            }
                        }
                        .padding(.horizontal, 24)
                    }

                    // Join button — hidden once Agora join is in flight
                    if joinedShowTitle == nil {
                        Button {
                            Task { await claimPairingCode() }
                        } label: {
                            ZStack {
                                if isJoining {
                                    ProgressView().tint(.white)
                                } else {
                                    Text("Join Show")
                                        .font(.custom(poppinsBold, size: 16))
                                }
                            }
                            .foregroundColor(.white)
                            .frame(maxWidth: .infinity)
                            .frame(height: 56)
                            .background(
                                RoundedRectangle(cornerRadius: 28)
                                    .fill(pairingCode.count == 6 ? Color.defaultTheme : Color.gray.opacity(0.4))
                            )
                        }
                        .disabled(pairingCode.count != 6 || isJoining)
                        .padding(.horizontal, 24)
                    }
                }
                .padding(.bottom, 40)
            }
        }
        .background(Color.backGround)
        .navigationBarHidden(true)
        .toast(isPresenting: $showhud) {
            AlertToast(displayMode: .hud, type: .regular, title: hudMsg)
        }
        .onAppear { codeFocused = true }
        .onDisappear {
            // Clean up Agora engine if user backs out before going live
            if !isLive && agoraManager.isJoined {
                agoraManager.leaveChannel()
            }
        }
    }

