    // MARK: - Leave Co-Host
    private func leaveCoHost() {
        agoraManager.leaveChannel()
        if !activeRoomId.isEmpty {
            SocketManagerService.shared.leaveInvitedCoHost(
                roomId: activeRoomId,
                userId: UserDefaults.userId,
                showId: "\(activeShowId)",
                coHostId: activeCoHostId
            )
        }
        if let activeCoHostId {
            Task { await leaveCoHostOnServer(coHostId: activeCoHostId) }
        }
        SocketManagerService.shared.removeChatListener()
        isLive = false
        presentationMode.wrappedValue.dismiss()
    }

    private func loadInviteDetail() async {
        guard let inviteId else { return }
        await MainActor.run {
            isLoadingInvite = true
            joinError = nil
        }
        do {
            let json = try await coHostRequest(path: "invite/\(inviteId)", method: "GET")
            guard (json["status"] as? String) == "success",
                  let data = json["data"] as? [String: Any] else {
                await MainActor.run {
                    inviteLoaded = false
                    isLoadingInvite = false
                    joinError = (json["message"] as? String) ?? "Could not load invite."
                }
                return
            }

            let show = data["show"] as? [String: Any]
                ?? data["schedule_show"] as? [String: Any]
            let host = data["host"] as? [String: Any]

            await MainActor.run {
                inviteLoaded = true
                isLoadingInvite = false
                inviteStatus = (data["status"] as? String) ?? "pending"
                inviteShowTitle = (show?["title"] as? String)
                    ?? (data["show_title"] as? String)
                    ?? "Live show"
                inviteHostName = (host?["name"] as? String)
                    ?? (host?["username"] as? String)
                    ?? "A seller"
                inviteScheduleShowId = Self.intValue(data["schedule_show_id"])
                    ?? Self.intValue(show?["id"])
                    ?? 0
                inviteHostUserId = Self.intValue(data["host_user_id"])
                    ?? Self.intValue(show?["user_id"])
                    ?? 0
            }
        } catch {
            await MainActor.run {
                inviteLoaded = false
                isLoadingInvite = false
                joinError = error.localizedDescription
            }
        }
    }

    private func loadEligibleProductsForInvite() async {
        guard let inviteId else { return }
        await MainActor.run { isRespondingToInvite = true }
        do {
            let json = try await coHostRequest(path: "invite/\(inviteId)/eligible-products", method: "GET")
            let productsJson = json["data"] as? [[String: Any]] ?? []
            let data = try JSONSerialization.data(withJSONObject: productsJson)
            let products = (try? JSONDecoder().decode([ProductDataModel1].self, from: data)) ?? []
            await MainActor.run {
                eligibleInviteProducts = products
                selectedInviteProductIds.removeAll()
                showInviteProductSelection = true
                isRespondingToInvite = false
            }
        } catch {
            await MainActor.run {
                isRespondingToInvite = false
                hudMsg = error.localizedDescription
                showhud = true
            }
        }
    }

    private func respondToInvite(accept: Bool, productIds: [Int]) async {
        guard let inviteId else { return }
        await MainActor.run { isRespondingToInvite = true }
        do {
            let json = try await coHostRequest(
                path: "invite/\(inviteId)/respond",
                method: "POST",
                body: [
                    "accept": accept,
                    "product_ids": productIds
                ]
            )
            guard (json["status"] as? String) == "success" else {
                await MainActor.run {
                    isRespondingToInvite = false
                    hudMsg = (json["message"] as? String) ?? "Could not update invite."
                    showhud = true
                }
                return
            }

            if !accept {
                await MainActor.run {
                    isRespondingToInvite = false
                    presentationMode.wrappedValue.dismiss()
                }
                return
            }

            let data = json["data"] as? [String: Any]
            let coHost = data?["co_host"] as? [String: Any]
            let showId = Self.intValue(data?["schedule_show_id"])
                ?? Self.intValue(coHost?["schedule_show_id"])
                ?? inviteScheduleShowId
            let hostUserId = Self.intValue(coHost?["host_user_id"]) ?? inviteHostUserId
            let coHostId = Self.intValue(coHost?["id"])

            await MainActor.run {
                activeCoHostId = coHostId
                activeShowId = showId
                isRespondingToInvite = false
            }

            if hostUserId > 0 && showId > 0 {
                await joinAgoraAsCoHost(hostUserId: hostUserId, showId: showId)
            } else {
                await MainActor.run {
                    agoraError = "Could not determine channel — missing show data."
                }
            }
        } catch {
            await MainActor.run {
                isRespondingToInvite = false
                hudMsg = error.localizedDescription
                showhud = true
            }
        }
    }

    private func coHostRequest(path: String, method: String, body: [String: Any]? = nil) async throws -> [String: Any] {
        guard let url = URL(string: "https://backend.bidcast.betaplanets.com/api/product/co-host/\(path)") else {
            return [:]
        }
        var request = URLRequest(url: url)
        request.httpMethod = method
        request.setValue("application/json", forHTTPHeaderField: "Accept")
        request.setValue("application/json", forHTTPHeaderField: "Content-Type")
        let scheme = "Be" + "arer"
        request.setValue("\(scheme) \(UserDefaults.accessToken)", forHTTPHeaderField: "Authorization")
        if let body {
            request.httpBody = try JSONSerialization.data(withJSONObject: body)
        }

        let (data, _) = try await URLSession.shared.data(for: request)
        return (try JSONSerialization.jsonObject(with: data)) as? [String: Any] ?? [:]
    }

    private func leaveCoHostOnServer(coHostId: Int) async {
        _ = try? await coHostRequest(path: "\(coHostId)/leave", method: "POST", body: [:])
    }

    // MARK: - Claim pairing code
    // POST /api/product/co-host/claim
    // Body: { "pairing_code": "<6-char>" }
    // Response (success): { status: "success", data: { ...show... } }
    // Response (error):   { status: "error",   message: "..." }
    private func claimPairingCode() async {
        guard pairingCode.count == 6 else { return }
        await MainActor.run {
            isJoining   = true
            joinError   = nil
            agoraError  = nil
        }

        guard let url = URL(string: "https://backend.bidcast.betaplanets.com/api/product/co-host/claim") else {
            await MainActor.run { isJoining = false; joinError = "Invalid URL." }
            return
        }

        var req = URLRequest(url: url)
        req.httpMethod = "POST"
        req.setValue("application/json", forHTTPHeaderField: "Content-Type")
        req.setValue("application/json", forHTTPHeaderField: "Accept")
        let scheme = "Be" + "arer"
        req.setValue("\(scheme) \(UserDefaults.accessToken)", forHTTPHeaderField: "Authorization")
        req.httpBody = try? JSONSerialization.data(withJSONObject: ["pairing_code": pairingCode])

        do {
            let (data, _) = try await URLSession.shared.data(for: req)
            let json = (try? JSONSerialization.jsonObject(with: data)) as? [String: Any]
            let status = (json?["status"] as? String) ?? ""

            if status == "success" {
                let row = json?["data"] as? [String: Any]

                // Basecamp #9934001770 (2026-05-29): "missing show data" fix.
                //
                // ROOT CAUSE: the claim response `data` is the PAIRING ROW, not
                // the show. The pairing row was created with `schedule_show_id`,
                // so:
                //   - the SHOW id lives under `schedule_show_id` (NOT `id`,
                //     which is the pairing row's own primary key), and
                //   - the HOST user id lives on the related show object
                //     (`schedule_show.user_id` / `show.user_id`), NOT the
                //     pairing row's `user_id` (which is the claimer / co-host).
                // The old code read row["id"] (pairing id) as the show id and
                // row["user_id"] (co-host) as the host — producing a wrong/zero
                // channel name and tripping the "missing show data" guard.
                //
                // We now resolve both from the most-specific source first and
                // fall back across every serialiser shape we've seen.
                let showObj = (row?["schedule_show"] as? [String: Any])
                    ?? (row?["show"] as? [String: Any])
                    ?? (row?["scheduleShow"] as? [String: Any])

                let showTitle = (showObj?["title"] as? String)
                    ?? (row?["show_title"] as? String)
                    ?? (row?["title"] as? String)
                    ?? "Show paired"

                // Helper: coerce Int-or-String JSON values to Int.
                func intValue(_ any: Any?) -> Int? {
                    if let v = any as? Int { return v }
                    if let s = any as? String, let v = Int(s) { return v }
                    if let d = any as? Double { return Int(d) }
                    return nil
                }

                // SHOW id: schedule_show_id (pairing FK) → nested show.id →
                // explicit show_id → (last resort) top-level id.
                let showId = intValue(row?["schedule_show_id"])
                    ?? intValue(showObj?["id"])
                    ?? intValue(row?["show_id"])
                    ?? intValue(row?["scheduleShowId"])
                    ?? intValue(row?["id"])
                    ?? 0

                // HOST user id: nested show.user_id → explicit host_user_id →
                // (last resort) row.user_id.
                let hostUserId = intValue(showObj?["user_id"])
                    ?? intValue(row?["host_user_id"])
                    ?? intValue(row?["hostUserId"])
                    ?? intValue(showObj?["userId"])
                    ?? intValue(row?["user_id"])
                    ?? 0

                await MainActor.run {
                    isJoining      = false
                    joinedShowTitle = showTitle
                }

                // Proceed to Agora only when we have valid identifiers
                if hostUserId > 0 && showId > 0 {
                    await joinAgoraAsCoHost(hostUserId: hostUserId, showId: showId)
                } else {
                    // FIX-5 (2026-05-30): Log raw response bytes so we can diagnose
                    // which fields the backend returned when channel resolution fails.
                    print("⚠️ CoHost claim raw data:", String(data: data, encoding: .utf8) ?? "nil")
                    await MainActor.run {
                        agoraError = "Could not determine channel — missing show data in response."
                    }
                }
            } else {
                await MainActor.run {
                    isJoining  = false
                    joinError  = (json?["message"] as? String)
                                 ?? "Invalid or expired code. Please try again."
                }
            }
        } catch {
            await MainActor.run {
                isJoining = false
                joinError = error.localizedDescription
            }
        }
    }

    // MARK: - Join Agora channel as second broadcaster
    //
    // Channel name: "live_room_\(hostUserId)_\(showId)" — matches RehearsalScreen.fetchAgoraToken exactly.
    // Token:        fetched via existing AgoraViewModel / POST /api/agora-token.
    // UID:          0 (let Agora auto-assign) so it is distinct from the host's UID.
    // Role:         broadcaster (publishCameraTrack + publishMicrophoneTrack = true).
    private func joinAgoraAsCoHost(hostUserId: Int, showId: Int) async {
        await MainActor.run { isJoiningAgora = true }

        // 1. Request camera and microphone permission
        let cameraOK = await AVCaptureDevice.requestAccess(for: .video)
        let audioOK  = await AVCaptureDevice.requestAccess(for: .audio)
        guard cameraOK && audioOK else {
            await MainActor.run {
                isJoiningAgora   = false
                permissionDenied = true
            }
            return
        }

        // 2. Build channel name — MUST match host's format exactly
        let channelName = "live_room_\(hostUserId)_\(showId)"

        // 3. Fetch broadcaster token (uid omitted → Agora auto-assigns distinct UID)
        await agoraViewModel.getAgoraToken(param: ["channel": channelName])
        let token = agoraViewModel.getAgoraDict?.data?.token ?? ""
        guard !token.isEmpty else {
            await MainActor.run {
                isJoiningAgora = false
                agoraError     = "Failed to obtain Agora token. Please try again."
            }
            return
        }

        // 4. Join as broadcaster (second publisher in same channel)
        agoraManager.joinChannel(asHost: true, channelName: channelName, token: token)
        activeRoomId = channelName
        activeShowId = showId
        if inviteId != nil {
            SocketManagerService.shared.setupSocket {
                SocketManagerService.shared.joinRoom(roomId: channelName, userId: UserDefaults.userId) {
                    syncCoHostProducts()
                }
                SocketManagerService.shared.observeRoomUpdates { room in
                    guard room.room_id == channelName else { return }
                    coHostShowProducts = room.products ?? []
                }
                SocketManagerService.shared.listenForChat(roomId: channelName)
                SocketManagerService.shared.listenForRoomEnded { endedRoomId in
                    guard endedRoomId == channelName else { return }
                    leaveCoHost()
                }
                SocketManagerService.shared.joinAsInvitedCoHost(
                    roomId: channelName,
                    userId: UserDefaults.userId,
                    showId: "\(showId)",
                    coHostId: activeCoHostId
                )
            }
        }

        await MainActor.run {
            isJoiningAgora = false
            isLive         = true
        }
    }

    private func syncCoHostProducts() {
        if let room = socketManager.rooms.first(where: { $0.room_id == activeRoomId }) {
            coHostShowProducts = room.products ?? []
        }
    }

    private func sendCoHostChatMessage() {
        let message = coHostCommentText.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !message.isEmpty, !activeRoomId.isEmpty else { return }
        SocketManagerService.shared.sendChat(
            roomId: activeRoomId,
            message: message,
            userId: UserDefaults.userId,
            userName: UserDefaults.userName,
            userImage: UserDefaults.profileURL
        )
        coHostCommentText = ""
    }

    private static func intValue(_ any: Any?) -> Int? {
        if let value = any as? Int { return value }
        if let value = any as? String { return Int(value) }
        if let value = any as? Double { return Int(value) }
        return nil
    }
}

